import { useQuery } from '@apollo/client';
import { GET_USER_REVIEWS } from '../graphql/queries';
import { getReview } from '../api';

const useReview = () => {
  const [review, setReview] = useState(null);
  const [error, setError] = useState(false);
  const { loading, error: errorLoading, data } = useQuery(GET_USER_REVIEWS, {
    variables: {
      userId: 'your-user-id',
    },
  });

  useEffect(() => {
    if (data && data.userReviews) {
      setReview(data.userReviews);
    }
  }, [data]);

  if (loading) {
    return <div>Loading...</div>;
  }

  if (errorLoading) {
    setError(true);
    return <p>Error loading reviews</p>;
  }


  return (
    <div>
      <h1>Review</h1>
      <p>{review?.text}</p>
      <button onClick={() => setReview(null)}>Clear</button>
    </div>
  );
};

export default useReview;
